# ── Convergence check ──────────────────────────────────────────────────────

check_convergence <- function(model, expected_facets, expected_interactions) {
  issues <- character(0)

  if (isSingular(model)) {
    issues <- c(issues, "WARNING: Model has singular fit (some variance components are exactly zero or near-zero)")
  }

  if (!is.null(model@optinfo$conv$lme4$messages)) {
    for (msg in model@optinfo$conv$lme4$messages) {
      issues <- c(issues, paste("OPTIMIZER WARNING:", msg))
    }
  }

  vc <- VarCorr(model)
  fitted_groups <- names(vc)

  valid_ixn <- Filter(function(ix) {
    parts <- strsplit(ix, ":")[[1]]
    all(parts %in% expected_facets)
  }, expected_interactions)
  expected_all <- c(expected_facets, valid_ixn)

  missing <- setdiff(expected_all, fitted_groups)
  if (length(missing) > 0) {
    issues <- c(issues, paste("MISSING variance components:", paste(missing, collapse = ", ")))
  }

  vc_df <- as.data.frame(vc)
  zero_vars <- vc_df$grp[vc_df$vcov < 1e-10]
  if (length(zero_vars) > 0) {
    issues <- c(issues, paste("NEAR-ZERO variance components:", paste(unique(zero_vars), collapse = ", ")))
  }

  if (length(issues) == 0) {
    cat("\n[OK] Convergence check PASSED: no singular fit, all components present, all variances > 0\n\n")
    return(TRUE)
  } else {
    cat("\n[!] Convergence issues detected:\n")
    for (iss in issues) cat("  -", iss, "\n")
    cat("\n")
    return(FALSE)
  }
}

